{"command": "python3 - <<'EOF'
import json, time, urllib.request

def version():
    with urllib.request.urlopen('https://api.ivxholding.com/api/ivx/version', timeout=20) as r:
        return json.loads(r.read())

def mint():
    req = urllib.request.Request('https://api.ivxholding.com/api/ivx/owner-passwordless-login',
        data=json.dumps({'email': 'iperez4242@gmail.com'}).encode(),
        headers={'Content-Type': 'application/json'}, method='POST')
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.loads(r.read()).get('accessToken')

def scopes(tok):
    body = json.dumps({'action': 'github_token_scopes', 'input': {}}).encode()
    req = urllib.request.Request('https://api.ivxholding.com/api/ivx/developer-deploy/action',
        data=body, headers={'Content-Type': 'application/json', 'Authorization': f'Bearer {tok}'}, method='POST')
    with urllib.request.urlopen(req, timeout=45) as r:
        return json.loads(r.read()).get('result', {})

# Poll up to ~50s for the Render restart to surface the new token
for attempt in range(5):
    v = version()
    tok = mint()
    json.dump({'accessToken': tok}, open('/tmp/owner_at.json', 'w'))
    res = scopes(tok)
    print(f"attempt {attempt+1}: boot={v.get('bootTime')} scopes={res.get('scopes')} workflow={res.get('hasWorkflowScope')}")
    if res.get('hasWorkflowScope'):
        print('WORKFLOW SCOPE LIVE')
        break
    time.sleep(10)
EOF"}

